INSERT INTO "tenders" ("id", "gem_bid_number", "title", "department", "category", "estimated_value_inr", "closing_date", "description", "source_text", "created_at", "updated_at") VALUES (2, 'GEM/2026/B/4012278', 'Supply of Office Stationery for Regional Training Centres', 'Department of Personnel and Training', 'Office supplies', 1850000, '2026-09-18', 'Annual stationery kit for 14 regional training centres.', 'Minimum turnover INR 25 lakh. GST and PAN mandatory. Udyam preferred.', '2026-09-04 16:59:19', '2026-09-04 16:59:19');
INSERT INTO "tenders" ("id", "gem_bid_number", "title", "department", "category", "estimated_value_inr", "closing_date", "description", "source_text", "created_at", "updated_at") VALUES (3, 'GEM/2026/B/5182940', 'Procurement of High-Capacity Server Racks & Cloud Infrastructure', 'Ministry of Electronics and Information Technology (MeitY)', 'IT & Datacenter Equipment', 85000000, '2026-11-15', 'Rate contract for turnkey supply, deployment, commissioning, and 5-year AMC of Tier-III datacenter blade servers, network switches, and hyperconverged infrastructure for National Informatics Centre (NIC) data hubs.', 'Minimum average annual turnover of INR 15,00,00,000 in the last three financial years. Valid GST and PAN mandatory. OEM authorization certificate required. Minimum 5 years of relevant experience in enterprise datacenter deployments. BIS and ISO 27001 technical certifications mandatory.', '2026-09-11 08:12:11', '2026-09-11 08:12:11');
INSERT INTO "tenders" ("id", "gem_bid_number", "title", "department", "category", "estimated_value_inr", "closing_date", "description", "source_text", "created_at", "updated_at") VALUES (4, 'GEM/2026/B/6290134', 'Solar PV Rooftop Systems & Battery Energy Storage (BESS) for Rural PHCs', 'Ministry of New and Renewable Energy (MNRE)', 'Renewable Energy Systems', 32000000, '2026-12-05', 'Supply, installation, and 5-year comprehensive maintenance of hybrid rooftop Solar PV systems with Lithium Ferro-Phosphate (LFP) storage across 40 remote Primary Health Centres.', 'Minimum average annual turnover INR 3,00,00,000. Valid GST and PAN mandatory. Active Udyam MSME preferred. MSE purchase preference applies. Minimum 3 years of experience in solar renewable installations. ALMM certified solar PV modules and BIS standard battery storage.', '2026-09-11 08:12:11', '2026-09-11 08:12:11');
INSERT INTO "tenders" ("id", "gem_bid_number", "title", "department", "category", "estimated_value_inr", "closing_date", "description", "source_text", "created_at", "updated_at") VALUES (5, 'GEM/2026/B/7304192', 'Supply of Advanced Life Support (ALS) Ambulances with Telemedicine Kit', 'National Health Mission (NHM)', 'Emergency Medical Vehicles', 67500000, '2026-10-25', 'Fabrication and supply of 15 fully equipped AIS-125 Type-D Advanced Life Support ambulances equipped with transport ventilators, biphasic defibrillators, 4G telemedicine link, and GPS fleet telemetry.', 'Minimum turnover INR 5,00,00,000 in last three financial years. Valid GST and PAN mandatory. Vehicle OEM manufacturer or ARAI-accredited body fabricator. AIS-125 Type D vehicle certification mandatory. Minimum 3 years of emergency vehicle fabrication experience.', '2026-09-11 08:12:11', '2026-09-11 08:12:11');
